function fewestCoins(coins, amount) {
  const sorted = [...coins].sort(function descending(left, right) {
    return right - left;
  });
  let left = amount;
  let count = 0;
  for (const coin of sorted) {
    while (left >= coin) {
      left -= coin;
      count += 1;
    }
  }
  return left === 0 ? count : -1;
}

